#include <iostream>
#include <vector>
using namespace std;

pair<long long, long long> solve_case(int n, long long k, const vector<long long>& a) {
    long long mn = 0, mx = 0;
    for (int i = 0; i < n; i++) {
        long long q = a[i] / k;
        long long r = a[i] % k;
        mn += q;
        mx += q + (r > 0 ? 1 : 0);
    }
    return {mn, mx};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        long long k;
        cin >> n >> k;
        vector<long long> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }
        auto [mn, mx] = solve_case(n, k, a);
        cout << mn << ' ' << mx << '\n';
    }

    return 0;
}
